### Description

This PR adds an `InvalidateElementCachesEvent` that is triggered by three methods in the `Elements` service:

* `invalidateAllCaches()`
* `invalidateCachesForElementType()`
* `invalidateCachesForElement()`

These methods are bottleneck methods that are called from a wide variety of places in the codebase whenever an element's caches need to be invalidated.

The event has a `$tags` property that is an array of `TagDependency` tag names that are being invalidated, so the listener can take an action when the caches are invalidated. Otherwise, there is no way to know when an Element's caches have been invalidated because the `TagDependency` information is stored appended to the cached data via whatever the current caching method is.

Throwing these events will greatly simplify implementing a variety of middleware that needs to know when an element's caches have been invalidated. Example usage:

```php
        // Listen for invalidated element caches
        Event::on(
            Elements::class,
            Elements::EVENT_INVALIDATE_ELEMENT_CACHES,
            static function (InvalidateElementCachesEvent $event) {
                $tags = $event->tags;
                // Do something with the $tags
            }
        );
```

Plugins like Blitz, Upper, and others that deal with cache invalidation would benefit from this, rather than having to roll their own solution.

These events are intentionally agnostic; you'd layer something useful on top of them. A common use-case would be to use these events in conjunction with something like: 

```php
        if (Craft::$app->getRequest()->getIsSiteRequest()) {
            // Start collecting cache tags
            Event::on(
                View::class,
                View::EVENT_BEFORE_RENDER_PAGE_TEMPLATE,
                static function (TemplateEvent $event) {
                    Craft::$app->getElements()->startCollectingCacheTags();
                }
            );
            // Stop collecting cache tags
            Event::on(
                View::class,
                View::EVENT_AFTER_RENDER_PAGE_TEMPLATE,
                static function (TemplateEvent $event) {
                    $tags = Craft::$app->getElements()->stopCollectingCacheTags();

                }
            );
        }
```

...so that you can collect the element caches on a given page, and when those events fire, do whatever you need to do to invalidate them.

In my case, I will be using a custom db table to store the rendering page's URI in conjunction with a JSON column type that has the array of TagDependency tag names, so whenever a tag is invalidated, I can do a reverse lookup to find all of the affected URIs.

First version of expression processing. Of the functions supported only: RIGHT, LEFT, MID, STRDATE (with "%y%m%d" format).

result:
```scala
contract processRecord(return, @state, @(recKey, recValues)) = {
  new processField, loop in {    
    contract processField(ret, s, fieldName) = {
      new BELNR, RECIPNT_NO, IDDAT, PARVW, IDDAT_colon_4, QUALF_colon_2, TEMP_IDTNR_colon_3 in {
        contract BELNR(ret0, s, recName) = {
          let s <- *s.set("local", "INP", *s.get(*recName, "BELNR")) in {
            let s <- *s.set("local", "OUTP", *s.get("local", "INP").slice(2, (2 + 8))) in {
              let s <- *s.set(*recName, "BELNR", *s.get("local", "OUTP")) in {
                ret0!(*s)
              }
            }
          }
        } |
        contract RECIPNT_NO(ret0, s, recName) = {
          let s <- *s.set(*recName, "RECIPNT_NO", *s.get(*recName, "RECIPNT_NO").slice(((*s.get(*recName, "RECIPNT_NO").length() - 1) - 8), (*s.get(*recName, "RECIPNT_NO").length() - 1))) in {
            ret0!(*s)
          }
        } |
        contract IDDAT(ret0, s, recName) = {
          new ret1 in {
            if(*s.get(*recName, "IDDAT") == "012") {
              let s <- *s.set(*s.get("CLAIM3N", "DATUM_colon_4"), *s.get(*recName, "DATUM_colon_3")) in {
                ret1!(*s)
              }
            }
            else {
              ret1!(*s)
            } |
            for(s<-ret1) {
              ret0!(*s)
            }
          }
        } |
        contract PARVW(ret0, s, recName) = {
          new ret1 in {
            if(*s.get(*recName, "PARVW") == "WE") {
              let s <- *s.set("CLAIM3N", "TEMP_ORT02", *s.get(*recName, "ORT02_colon_3")) in {
                ret1!(*s)
              }
            }
            else {
              ret1!(*s)
            } |
            for(s<-ret1) {
              ret0!(*s)
            }
          }
        } |
        contract IDDAT_colon_4(ret0, s, recName) = {
          new ret1 in {
            if(*s.get(*recName, "IDDAT_colon_4") == "032") {
              let s <- *s.set(*s.get("E2EDP01", "DATUM_colon_3"), *s.get(*recName, "DATUM_colon_2")) in {
                ret1!(*s)
              }
            }
            else {
              ret1!(*s)
            } |
            for(s<-ret1) {
              ret0!(*s)
            }
          }
        } |
        contract QUALF_colon_2(ret0, s, recName) = {
          new ret1 in {
            if(*s.get(*recName, "QUALF_colon_2") == "003") {
              let s <- *s.set("E2EDP01", "TEMP_IDTNR", *s.get(*recName, "IDTNR")) in {
                let s <- *s.set("E2EDP01", "TEMP_IDTNR_colon_4", *s.get(*recName, "IDTNR").slice(11, (11 + 1))) in {
                  ret1!(*s)
                }
              }
            }
            else {
              ret1!(*s)
            } |
            for(s<-ret1) {
              new ret1 in {
                if(*s.get(*recName, "QUALF_colon_2") == "007") {
                  let s <- *s.set("E2EDP01", "TEMP_IDTNR_colon_2", *s.get(*recName, "IDTNR")) in {
                    let s <- *s.set("E2EDP01", "TEMP_IDTNR_colon_3", *s.get(*recName, "MFRNR")) in {
                      ret1!(*s)
                    }
                  }
                }
                else {
                  ret1!(*s)
                } |
                for(s<-ret1) {
                  ret0!(*s)
                }
              }
            }
          }
        } |
        contract TEMP_IDTNR_colon_3(ret0, s, recName) = {
          ret0!(*s)
        } |
        match *fieldName {
          "BELNR" => { for(newS <- BELNR!?(*s)) { ret!(*newS) } }
          "RECIPNT_NO" => { for(newS <- RECIPNT_NO!?(*s)) { ret!(*newS) } }
          "IDDAT" => { for(newS <- IDDAT!?(*s)) { ret!(*newS) } }
          "PARVW" => { for(newS <- PARVW!?(*s)) { ret!(*newS) } }
          "IDDAT_colon_4" => { for(newS <- IDDAT_colon_4!?(*s)) { ret!(*newS) } }
          "QUALF_colon_2" => { for(newS <- QUALF_colon_2!?(*s)) { ret!(*newS) } }
          "TEMP_IDTNR_colon_3" => { for(newS <- TEMP_IDTNR_colon_3!?(*s)) { ret!(*newS) } }
          _ => ret!(*s)
        }
      }
    } |
    contract loop(@keys, @s) = {
      match keys {
        Set(head ...tail) => {
          new newState in {
            for (newState <- processField!?(s, head)) { loop!(tail, *newState) }
          }
        }
        _ => { return!(s) }
      }
    } |
    loop!(recValues.keys(), state)
  }
}
```

I removed the single db limitation from get_catalog.

Reason: when using different quoting policies in a dbt project, they are stored as separate schema info. The previous check we did disallowed multiple schema info, and I don't see a good reason not to allow multiple information schema in this case.

